namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }

    public double AverageRating => TotalRatings > 0 ? (double)RatingSum / TotalRatings : 0;
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes =
        [
            new Recipe
            {
                Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Description = "A simple, classic pizza with fresh mozzarella and basil.",
                Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
                Steps = ["Preheat oven to 475°F (245°C).", "Roll out dough on a floured surface.", "Spread crushed tomatoes over the dough.", "Tear mozzarella and distribute evenly.", "Bake for 10–12 minutes until crust is golden.", "Top with fresh basil and a drizzle of olive oil."],
                TotalRatings = 12, RatingSum = 52
            },
            new Recipe
            {
                Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
                Description = "Creamy Roman pasta with eggs, cheese, and pancetta.",
                Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Pecorino Romano", "Black pepper"],
                Steps = ["Cook spaghetti in salted boiling water until al dente.", "Fry pancetta until crispy.", "Whisk eggs with grated Pecorino and pepper.", "Toss hot pasta with pancetta, then quickly stir in egg mixture off heat.", "Serve immediately with extra cheese and pepper."],
                TotalRatings = 8, RatingSum = 38
            },
            new Recipe
            {
                Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
                Description = "Tender chicken in a rich, spiced tomato-cream sauce.",
                Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger"],
                Steps = ["Marinate chicken in yogurt and spices for at least 1 hour.", "Grill or broil chicken until charred.", "Sauté onion, garlic, and ginger in a pan.", "Add tomato sauce and simmer 15 minutes.", "Stir in cream, add chicken, and simmer 10 more minutes.", "Serve over basmati rice."],
                TotalRatings = 15, RatingSum = 70
            },
            new Recipe
            {
                Id = 4, Title = "Vegetable Pad Thai", Category = "Asian",
                Description = "Sweet, sour, and savory stir-fried rice noodles.",
                Ingredients = ["Rice noodles", "Tofu", "Bean sprouts", "Peanuts", "Lime", "Fish sauce", "Tamarind paste", "Brown sugar", "Eggs"],
                Steps = ["Soak rice noodles in warm water for 30 minutes.", "Press and cube tofu, then pan-fry until golden.", "Whisk together fish sauce, tamarind paste, and brown sugar.", "Stir-fry noodles with sauce, push aside, scramble eggs.", "Toss everything together with bean sprouts.", "Serve with crushed peanuts and lime wedges."],
                TotalRatings = 10, RatingSum = 43
            },
            new Recipe
            {
                Id = 5, Title = "Chocolate Lava Cake", Category = "Desserts",
                Description = "Rich chocolate cake with a molten center.",
                Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour", "Vanilla extract"],
                Steps = ["Preheat oven to 425°F (220°C). Grease ramekins.", "Melt chocolate and butter together.", "Whisk eggs, sugar, and vanilla, then fold into chocolate mixture.", "Add flour and stir until just combined.", "Pour into ramekins and bake 12–14 minutes.", "Invert onto plates and serve immediately."],
                TotalRatings = 20, RatingSum = 95
            },
            new Recipe
            {
                Id = 6, Title = "Guacamole", Category = "Mexican",
                Description = "Fresh, chunky avocado dip with lime and cilantro.",
                Ingredients = ["Avocados", "Lime juice", "Red onion", "Cilantro", "Jalapeño", "Tomato", "Salt"],
                Steps = ["Halve and pit avocados, scoop into a bowl.", "Mash to desired consistency.", "Stir in diced onion, tomato, jalapeño, and cilantro.", "Add lime juice and salt to taste.", "Serve immediately with tortilla chips."],
                TotalRatings = 6, RatingSum = 27
            },
            new Recipe
            {
                Id = 7, Title = "Beef Tacos", Category = "Mexican",
                Description = "Seasoned ground beef tacos with fresh toppings.",
                Ingredients = ["Ground beef", "Taco seasoning", "Corn tortillas", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Salsa"],
                Steps = ["Brown ground beef in a skillet over medium-high heat.", "Add taco seasoning and water, simmer until thickened.", "Warm tortillas in a dry pan.", "Assemble tacos with beef, lettuce, tomato, cheese, sour cream, and salsa."],
                TotalRatings = 9, RatingSum = 40
            },
            new Recipe
            {
                Id = 8, Title = "Miso Soup", Category = "Asian",
                Description = "Light, umami-rich Japanese soup.",
                Ingredients = ["Dashi stock", "White miso paste", "Silken tofu", "Wakame seaweed", "Green onions"],
                Steps = ["Bring dashi stock to a gentle simmer.", "Soak wakame in water for 5 minutes, then drain.", "Cube tofu into small pieces.", "Dissolve miso paste into the broth (do not boil).", "Add tofu and wakame, heat through.", "Serve garnished with sliced green onions."],
                TotalRatings = 5, RatingSum = 22
            },
        ];
        _nextId = 9;
    }

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().Order().ToList();

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalRatings++;
            recipe.RatingSum += stars;
        }
    }

    public Recipe AddRecipe(string title, string category, string description, List<string> ingredients, List<string> steps)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = title,
            Category = category,
            Description = description,
            Ingredients = ingredients,
            Steps = steps
        };
        _recipes.Add(recipe);
        return recipe;
    }
}

@using RecipeHub.Services
@rendermode InteractiveServer
@inject RecipeService Recipes

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= _displayRating ? "filled" : "")"
              @onclick="() => Rate(star)"
              @onmouseover="() => _displayRating = star"
              @onmouseout="() => _displayRating = 0"
              role="button"
              title="Rate @star star@(star > 1 ? "s" : "")">★</span>
    }
    @if (_submitted)
    {
        <span class="rating-thanks">Thanks for rating!</span>
    }
</div>

<style>
    .star-rating {
        display: inline-flex;
        align-items: center;
        gap: 2px;
        font-size: 1.6rem;
    }
    .star {
        color: #ccc;
        cursor: pointer;
        transition: color 0.15s, transform 0.15s;
        user-select: none;
    }
    .star:hover,
    .star.filled {
        color: #f5a623;
        transform: scale(1.15);
    }
    .rating-thanks {
        margin-left: 0.5rem;
        font-size: 0.9rem;
        color: #28a745;
        font-weight: 500;
    }
</style>

@code {
    [Parameter] public int RecipeId { get; set; }

    private int _displayRating;
    private bool _submitted;

    private void Rate(int stars)
    {
        Recipes.AddRating(RecipeId, stars);
        _submitted = true;
        _displayRating = stars;
    }
}

@page "/category/{CategoryName}"
@using RecipeHub.Services
@inject RecipeService Recipes

<PageTitle>@CategoryName Recipes — RecipeHub</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active" aria-current="page">@CategoryName</li>
    </ol>
</nav>

<h1>@CategoryName Recipes</h1>

@{
    var recipes = Recipes.GetByCategory(CategoryName ?? "");
}

@if (recipes.Count == 0)
{
    <p class="text-muted">No recipes found in this category.</p>
}
else
{
    <div class="row row-cols-1 row-cols-md-2 g-4 mt-2">
        @foreach (var recipe in recipes)
        {
            <div class="col">
                <div class="card h-100 shadow-sm">
                    <div class="card-body">
                        <h5 class="card-title">
                            <a href="/recipe/@recipe.Id">@recipe.Title</a>
                        </h5>
                        <p class="card-text">@recipe.Description</p>
                        <div class="text-warning">
                            @for (int i = 1; i <= 5; i++)
                            {
                                <span>@(i <= (int)Math.Round(recipe.AverageRating) ? "★" : "☆")</span>
                            }
                            <small class="text-muted ms-1">(@recipe.TotalRatings ratings)</small>
                        </div>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter] public string? CategoryName { get; set; }
}

@page "/recipe/{Id:int}"
@using RecipeHub.Services
@inject RecipeService Recipes

@if (_recipe is null)
{
    <PageTitle>Recipe Not Found — RecipeHub</PageTitle>
    <h1>Recipe Not Found</h1>
    <p>The recipe you're looking for doesn't exist.</p>
    <a href="/">Back to Home</a>
}
else
{
    <PageTitle>@_recipe.Title — RecipeHub</PageTitle>

    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="/category/@_recipe.Category">@_recipe.Category</a></li>
            <li class="breadcrumb-item active" aria-current="page">@_recipe.Title</li>
        </ol>
    </nav>

    <h1>@_recipe.Title</h1>
    <p class="lead">@_recipe.Description</p>

    <div class="mb-3">
        <strong>Average Rating:</strong>
        <span class="text-warning">
            @for (int i = 1; i <= 5; i++)
            {
                <span>@(i <= (int)Math.Round(_recipe.AverageRating) ? "★" : "☆")</span>
            }
        </span>
        <small class="text-muted">(@_recipe.TotalRatings ratings)</small>
    </div>

    <h3>Ingredients</h3>
    <ul class="list-group list-group-flush mb-4">
        @foreach (var ingredient in _recipe.Ingredients)
        {
            <li class="list-group-item">@ingredient</li>
        }
    </ul>

    <h3>Steps</h3>
    <ol class="list-group list-group-numbered mb-4">
        @foreach (var step in _recipe.Steps)
        {
            <li class="list-group-item">@step</li>
        }
    </ol>

    <div class="card bg-light p-3 mb-4">
        <h5 class="mb-2">Rate this recipe</h5>
        <StarRating RecipeId="@_recipe.Id" />
    </div>
}

@code {
    [Parameter] public int Id { get; set; }

    private RecipeHub.Models.Recipe? _recipe;

    protected override void OnInitialized()
    {
        _recipe = Recipes.GetById(Id);
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeHub.Services
@inject RecipeService Recipes
@inject NavigationManager Nav

<PageTitle>Submit a Recipe — RecipeHub</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (_submitted)
{
    <div class="alert alert-success">
        <strong>Recipe submitted!</strong> Your recipe "<strong>@_title</strong>" has been added.
        <a href="/recipe/@_newRecipeId">View it here</a>.
    </div>
}

<EditForm FormName="submitRecipe" Model="this" OnValidSubmit="HandleSubmit">
    <DataAnnotationsValidator />

    <div class="mb-3">
        <label for="title" class="form-label">Recipe Title</label>
        <InputText id="title" class="form-control" @bind-Value="_title" placeholder="e.g., Grandma's Apple Pie" />
    </div>

    <div class="mb-3">
        <label for="category" class="form-label">Category</label>
        <InputText id="category" class="form-control" @bind-Value="_category" placeholder="e.g., Desserts, Italian, Asian" />
    </div>

    <div class="mb-3">
        <label for="description" class="form-label">Description</label>
        <InputTextArea id="description" class="form-control" @bind-Value="_description" rows="2" placeholder="A brief description of your recipe" />
    </div>

    <div class="mb-3">
        <label for="ingredients" class="form-label">Ingredients</label>
        <InputTextArea id="ingredients" class="form-control" @bind-Value="_ingredients" rows="5" placeholder="One ingredient per line" />
        <div class="form-text">Enter one ingredient per line.</div>
    </div>

    <div class="mb-3">
        <label for="steps" class="form-label">Steps</label>
        <InputTextArea id="steps" class="form-control" @bind-Value="_steps" rows="5" placeholder="One step per line" />
        <div class="form-text">Enter one step per line.</div>
    </div>

    <button type="submit" class="btn btn-primary" disabled="@(!IsFormValid)">Submit Recipe</button>
</EditForm>

@code {
    private string _title = string.Empty;
    private string _category = string.Empty;
    private string _description = string.Empty;
    private string _ingredients = string.Empty;
    private string _steps = string.Empty;
    private bool _submitted;
    private int _newRecipeId;

    private bool IsFormValid =>
        !string.IsNullOrWhiteSpace(_title) &&
        !string.IsNullOrWhiteSpace(_category) &&
        !string.IsNullOrWhiteSpace(_ingredients) &&
        !string.IsNullOrWhiteSpace(_steps);

    private void HandleSubmit()
    {
        if (!IsFormValid) return;

        var ingredientList = _ingredients
            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .ToList();

        var stepList = _steps
            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .ToList();

        var recipe = Recipes.AddRecipe(_title, _category, _description, ingredientList, stepList);
        _newRecipeId = recipe.Id;
        _submitted = true;
    }
}

