        !string.IsNullOrWhiteSpace(_category) &&
        !string.IsNullOrWhiteSpace(_ingredients) &&
        !string.IsNullOrWhiteSpace(_steps);

    private void HandleSubmit()
    {
        if (!IsFormValid) return;

        var ingredientList = _ingredients
            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .ToList();

        var stepList = _steps
            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .ToList();

        var recipe = Recipes.AddRecipe(_title, _category, _description, ingredientList, stepList);
        _newRecipeId = recipe.Id;
        _submitted = true;
    }
}
"}

